ction:column;gap:6px}\n.gba-cal-event{border-left:3px solid var(--ink);padding:6px 9px;background:var(--card2);font-size:12px;line-height:1.5}\n.gba-cal-event b{display:block;margin-bottom:3px;font-size:12px;color:var(--ink)}\n.gba-cal-event p{margin:0;color:var(--ink2);font-size:11.5px}\n.gba-badge-today{display:inline-block;padding:1px 6px;font:700 10px var(--font-num);background:var(--ink);color:var(--screen);border:1px solid var(--ink);border-radius:0}\n.gba-badge-school{display:inline-block;padding:1px 6px;font:700 10px var(--font-ui);border:2px double var(--ink);background:var(--card2);color:var(--ink);border-radius:0}\n.gba-badge-holiday{display:inline-block;padding:1px 6px;font:600 10px var(--font-ui);border:1px solid var(--ink);background:var(--card);color:var(--ink);border-radius:0}\n.gba-badge-fest{display:inline-block;padding:1px 6px;font:600 10px var(--font-ui);border:1px dashed var(--hair);background:var(--card2);color:var(--ink);border-radius:0}\n\n/* ===== 破军 LIME 互换通讯录样式 ===== */\n.lime-contact-list{display:flex;flex-direction:column;gap:8px;margin-bottom:12px}\n.lime-contact-card{display:flex;align-items:center;cursor:pointer;gap:10px}\n.lime-badge-added{display:inline-block;padding:1px 5px;font:700 9px var(--font-ui);border:1px solid var(--ink);background:var(--card2);color:var(--ink);border-radius:0;margin-left:4px}\n.lime-badge-unadded{display:inline-block;padding:1px 5px;font:9px var(--font-ui);border:1px dashed var(--hair);background:transparent;color:var(--muted);border-radius:0;margin-left:4px}\n.lime-contact-card.muted-card{border-style:dashed;opacity:0.8}\n.gba-btn-chat{padding:4px 9px;font:11px var(--font-ui);border:1px solid var(--ink);background:var(--surface);color:var(--ink);border-radius:0;cursor:pointer;white-space:nowrap}\n.gba-btn-chat:hover{background:var(--ink);color:var(--screen)}\n.gba-btn-action{padding:7px 10px;font:12px var(--font-ui);border:1px solid var(--hair);background:var(--surface);color:var(--ink);text-align:left;border-radius:0;cursor:pointer}\n.gba-btn-action:hover{border-color:var(--ink);background:var(--card2)}\n.gba-lime-hint{margin-top:8px;padding:8px 10px;background:var(--card2);border-left:3px solid var(--hair);font-size:11.5px;color:var(--ink2);line-height:1.6}\n.gba-lime-hint strong{color:var(--ink)}\n\n\n\n/* 副 API 表单随手机宽度收拢；长正文、提示词与补丁均留在卡片内。 */\n.rk-correction { min-width: 0; }\n.rk-correction p { color: var(--muted); font-size: 12px; line-height: 1.6; margin: 8px 0; overflow-wrap: anywhere; }\n.rk-correction label { display: grid; min-width: 0; gap: 5px; margin: 10px 0; font-size: 12px; }\n.rk-correction input, .rk-correction textarea, .rk-correction select { display: block; width: 100%; min-width: 0; box-sizing: border-box; padding: 9px; border: 1px solid var(--hair); border-radius: 3px; background: var(--card2); color: var(--ink); font: inherit; line-height: 1.5; }\n.rk-correction textarea { resize: vertical; }\n.rk-correction textarea[readonly] { font-size: 11px; }\n.rk-correction-model { display: flex; align-items: end; gap: 8px; }\n.rk-correction-model label { flex: 1; }\n.rk-correction-model button { flex: none; margin-bottom: 10px; white-space: nowrap; }\n.rk-correction-fields { display: grid; grid-template-columns: minmax(0, 1fr) 100px; gap: 10px; }\n.rk-correction-fold { margin: 12px 0; padding: 10px; border: 1px solid var(--hair); background: var(--card); }\n.rk-correction-fold summary { cursor: pointer; font-size: 12px; font-weight: 600; line-height: 1.6; }\n.rk-correction-actions { display: flex; gap: 8px; flex-wrap: wrap; margin: 10px 0; }\n.rk-correction button { padding: 8px 10px; background: var(--card2); color: var(--ink); border: 1px solid var(--hair); border-radius: 3px; font: 12px var(--font-ui); line-height: 1.5; cursor: pointer; }\n.rk-correction button.rk-correction-primary { background: var(--ink); color: var(--screen); border-color: var(--ink); }\n.rk-correction button:disabled { opacity: .45; cursor: default; }\n.rk-correction :is(input, textarea, select, button, summary):focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; }\n.rk-correction pre { white-space: pre-wrap; overflow-wrap: anywhere; max-height: 260px; overflow: auto; margin: 0; padding: 10px; background: var(--card2); font-size: 11px; line-height: 1.5; }\n.rk-correction [data-status] { min-height: 2.4em; }\n@media (max-width: 360px) { .rk-correction-fields { grid-template-columns: minmax(0, 1fr) 85px; gap: 8px; } .rk-correction-fold { padding: 8px; } }\n\n/* 自动开关用原生复选框，避免通用输入框样式将它撑满一行。 */\n.rk-correction label.rk-correction-auto { display: flex; align-items: center; gap: 8px; }\n.rk-correction .rk-correction-auto input { width: 16px; height: 16px; flex: none; margin: 0; padding: 0; accent-color: var(--ink); }\n.rk-correction [data-auto-status] { border-left: 2px solid var(--ink); padding-left: 8px; }\n\u003c/style>\n\u003cstyle>\n/* Color-block status module. Kept inside the dossier; shell and wheel keep their theme. */\n#blazer-body.gba-status {\n  --gba-ink: #1b2748;\n  --gba-navy: #2b4773;\n  --gba-navy-light: #3d608b;\n  --gba-paper: #fff3d6;\n  --gba-paper-shade: #e9dcb9;\n  --gba-muted: #526076;\n  --gba-gold: #efbd4f;\n  --gba-teal: #319e8e;\n  --gba-teal-light: #82d1ad;\n  --gba-red: #c85b46;\n  --ink: var(--gba-ink);\n  --ink2: #35425b;\n  --muted: var(--gba-muted);\n  --card: var(--gba-paper);\n  --card2: var(--gba-paper-shade);\n  --hair: #82908f;\n  --sky: #205f79;\n  --crimson: var(--gba-red);\n  --press: var(--gba-paper-shade);\n  color: var(--gba-ink);\n  background: #223759;\n  padding: 2px 0 16px;\n  font-size: 13px;\n  line-height: 1.65;\n  overflow-wrap: anywhere;\n  scrollbar-color: var(--gba-gold) var(--gba-ink);\n  color-scheme: light;\n}\n\n#blazer-body.gba-status *,\n#blazer-body.gba-status *::before,\n#blazer-body.gba-status *::after {\n  box-sizing: border-box;\n}\n\n#blazer-body.gba-status .card1 {\n  margin: 12px 10px;\n  padding: 12px;\n  border: 2px solid var(--gba-ink);\n  border-radius: 0;\n  background: var(--gba-paper);\n  color: var(--gba-ink);\n  box-shadow: 2px 2px 0 #14203a;\n  min-width: 0;\n}\n\n#blazer-body.gba-status .ct {\n  background: var(--gba-navy);\n  color: var(--gba-paper);\n  border-bottom: 2px solid var(--gba-gold);\n  padding: 6px 9px;\n  margin: 12px 0 9px;\n  font-family: var(--font-ui);\n  font-size: 12px;\n  font-weight: 700;\n  line-height: 1.5;\n  letter-spacing: .5px;\n}\n\n#blazer-body.gba-status .card1 > .ct:first-child {\n  margin: -12px -12px 12px;\n}\n\n#blazer-body.gba-status .card-avatar {\n  background: var(--gba-gold);\n  color: var(--gba-ink);\n  border: 2px solid var(--gba-ink);\n  box-shadow: none;\n}\n\n#blazer-body.gba-status .card-rank-badge {\n  display: inline-block;\n  vertical-align: middle;\n  min-width: 27px;\n  margin-left: 3px;\n  padding: 2px 5px;\n  border: 2px solid var(--gba-ink);\n  border-radius: 0;\n  background: var(--gba-gold);\n  color: var(--gba-ink);\n  font: 700 13px/1.3 var(--font-num);\n  text-align: center;\n  text-shadow: none;\n  white-space: nowrap;\n}\n\n/* 觉醒是独立布尔状态，使用文字和边框区分，不伪装成等级奖励。 */\n#blazer-body.gba-status .gba-awakening {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  margin: 10px 0;\n  padding: 7px 9px;\n  border: 1px solid #82908f;\n  background: var(--gba-paper-shade);\n  color: var(--gba-muted);\n  font-size: 12px;\n}\n\n#blazer-body.gba-status .gba-awakening strong {\n  color: var(--gba-ink);\n  font-weight: 700;\n}\n\n#blazer-body.gba-status .gba-awakening[data-awakened='true'] {\n  border-left: 4px solid var(--gba-red);\n}\n\n/* A navy field keeps the chart distinct from the paper explanation beneath it. */\n#blazer-body.gba-status .radar-container {\n  background: var(--gba-navy);\n  border: 2px solid var(--gba-ink);\n  padding: 12px 0;\n  min-width: 0;\n}\n\n#blazer-body.gba-status .radar-svg {\n  display: block;\n  width: min(100%, 320px);\n  max-height: none;\n  height: auto;\n  overflow: visible;\n}\n\n#blazer-body.gba-status .radar-web,\n#blazer-body.gba-status .radar-web-spoke,\n#blazer-body.gba-status .radar-spoke {\n  stroke: #91abc0;\n  stroke-width: 1;\n  stroke-opacity: .7;\n}\n\n#blazer-body.gba-status .radar-web { fill: none; }\n\n#blazer-body.gba-status .radar-polygon {\n  fill: var(--gba-teal);\n  fill-opacity: .72;\n  stroke: var(--gba-gold);\n  stroke-width: 2.2;\n  filter: none;\n}\n\n#blazer-body.gba-status .radar-point {\n  fill: var(--gba-paper);\n  stroke: var(--gba-ink);\n  stroke-width: 2;\n}\n\n#blazer-body.gba-status .radar-label {\n  fill: var(--gba-paper);\n  font-family: var(--font-ui);\n  font-size: 10px;\n  font-weight: 600;\n}\n\n#blazer-body.gba-status .radar-rank-badge {\n  fill: var(--gba-gold);\n  font: 700 12px var(--font-num);\n}\n\n#blazer-body.gba-status .radar-legend,\n#blazer-body.gba-status .gba-note {\n  color: var(--gba-muted);\n  font-size: 12px;\n  line-height: 1.65;\n  margin: 9px 0 0;\n}\n\n#blazer-body.gba-status .noble-art-block {\n  margin-top: 10px;\n  padding: 9px 10px;\n  border: 1px solid #a1a58f;\n  border-left: 4px solid var(--gba-teal);\n  border-radius: 0;\n  background: var(--gba-paper-shade);\n}\n\n#blazer-body.gba-status .noble-art-title {\n  color: var(--gba-ink);\n  font: 700 13px/1.6 var(--font-ui);\n  flex-wrap: wrap;\n}\n\n#blazer-body.gba-status .noble-art-desc {\n  color: var(--ink2);\n  font-size: 12px;\n  line-height: 1.7;\n}\n\n/* Native details provides one full-width, keyboard-operable contact control. */\n#blazer-body.gba-status .roster-list {\n  padding: 10px;\n  gap: 12px;\n}\n\n#blazer-body.gba-status details.roster-card {\n  display: block;\n  padding: 0;\n  margin: 0;\n  border: 2px solid var(--gba-ink);\n  border-radius: 0;\n  background: var(--gba-paper);\n  color: var(--gba-ink);\n  box-shadow: 2px 2px 0 #14203a;\n  cursor: auto;\n  min-width: 0;\n}\n\n#blazer-body.gba-status .gba-contact-summary {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 11px 10px;\n  min-height: 68px;\n  background: var(--gba-navy);\n  color: var(--gba-paper);\n  list-style: none;\n  cursor: pointer;\n  touch-action: manipulation;\n}\n\n#blazer-body.gba-status .gba-contact-summary::-webkit-details-marker { display: none; }\n#blazer-body.gba-status .gba-contact-summary::marker { content: ''; }\n\n#blazer-body.gba-status .gba-contact-summary:hover {\n  background: var(--gba-navy-light);\n}\n\n#blazer-body.gba-status .gba-contact-summary:focus-visible {\n  outline: 3px solid var(--gba-gold);\n  outline-offset: -3px;\n}\n\n#blazer-body.gba-status .gba-contact[open] > .gba-contact-summary {\n  border-bottom: 3px solid var(--gba-gold);\n}\n\n#blazer-body.gba-status .roster-ava {\n  width: 42px;\n  height: 44px;\n  flex: 0 0 42px;\n  border: 2px solid var(--gba-ink);\n  border-radius: 0;\n  background: var(--gba-gold);\n  color: var(--gba-ink);\n  font: 700 24px/1 var(--font-title);\n  box-shadow: none;\n}\n\n#blazer-body.gba-status .roster-info {\n  flex: 1 1 auto;\n  min-width: 0;\n  overflow-wrap: anywhere;\n}\n\n#blazer-body.gba-status .roster-name {\n  color: inherit;\n  font-size: 14px;\n  font-weight: 700;\n  line-height: 1.7;\n}\n\n#blazer-body.gba-status .roster-device {\n  color: var(--ink2);\n  font-size: 12px;\n  line-height: 1.7;\n  white-space: normal;\n  overflow-wrap: anywhere;\n}\n\n#blazer-body.gba-status .gba-contact-summary .roster-device {\n  color: #dae6e5;\n  margin-top: 3px;\n}\n\n#blazer-body.gba-status .gba-disclosure {\n  flex: 0 0 auto;\n  color: var(--gba-gold);\n  font: 700 12px/1.5 var(--font-ui);\n  text-align: center;\n}\n\n#blazer-body.gba-status .gba-disclosure::before {\n  content: '▸';\n  display: block;\n  font-size: 17px;\n  line-height: 1;\n}\n\n#blazer-body.gba-status .gba-contact[open] .gba-disclosure::before { content: '▾'; }\n\n#blazer-body.gba-status .gba-contact-body {\n  padding: 12px;\n  color: var(--gba-ink);\n  background: var(--gba-paper);\n  min-width: 0;\n}\n\n#blazer-body.gba-status .gba-contact-body > .roster-device + .roster-device {\n  margin-top: 6px;\n}\n\n#blazer-body.gba-status .gba-contact-body dl {\n  display: grid;\n  grid-template-columns: max-content minmax(0, 1fr);\n  gap: 7px 10px;\n  margin: 0;\n}\n\n#blazer-body.gba-status .gba-contact-body dt { color: var(--gba-muted); }\n#blazer-body.gba-status .gba-contact-body dd { margin: 0; min-width: 0; }\n\n/* Solid meters have a single light edge; neither value is indicated by color alone. */\n#blazer-body.gba-status .gba-bond-panel {\n  margin-top: 12px;\n  padding-top: 12px;\n  border-top: 2px solid #bcc1a7;\n}\n\n#blazer-body.gba-status .gba-metric {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 4px 10px;\n  color: var(--gba-ink);\n  font-size: 12px;\n  margin: 9px 0 5px;\n}\n\n#blazer-body.gba-status .gba-metric strong,\n#blazer-body.gba-status .gba-metric b {\n  font: 700 15px/1.4 var(--font-num);\n  color: var(--gba-ink);\n}\n\n#blazer-body.gba-status .gba-meter {\n  height: 16px;\n  width: 100%;\n  border: 2px solid var(--gba-ink);\n  background: #c6c9b2;\n  overflow: hidden;\n}\n\n#blazer-body.gba-status .gba-meter > span {\n  display: block;\n  height: 100%;\n  min-width: 0;\n  max-width: 100%;\n  background: var(--gba-teal);\n  border-top: 3px solid var(--gba-teal-light);\n}\n\n#blazer-body.gba-status .gba-meter[data-kind='support'] > span {\n  background: #d59635;\n  border-top-color: #ffde83;\n}\n\n#blazer-body.gba-status .gba-support-track {\n  display: flex;\n  gap: 5px;\n  margin: 9px 0 0;\n  padding: 0;\n  list-style: none;\n}\n\n#blazer-body.gba-status .gba-support-track li {\n  flex: 1 1 0;\n  min-width: 0;\n  padding: 5px 2px;\n  border: 1px solid #8c967f;\n  background: var(--gba-paper-shade);\n  color: #53616c;\n  font: 700 13px/1.5 var(--font-num);\n  text-align: center;\n}\n\n#blazer-body.gba-status .gba-support-track li[data-achieved='true'] {\n  border-color: var(--gba-ink);\n  border-bottom: 3px solid var(--gba-gold);\n  padding-bottom: 3px;\n  background: var(--gba-navy);\n  color: var(--gba-paper);\n}\n\n#blazer-body.gba-status .gba-support-track small {\n  display: block;\n  font: 11px/1.4 var(--font-num);\n}\n\n#blazer-body.gba-status .gba-unknown {\n  color: var(--gba-muted);\n  font-size: 12px;\n  font-style: normal;\n}\n\n#blazer-body.gba-status .gba-romance-panel {\n  border-top: 2px solid var(--gba-red);\n  margin-top: 14px;\n  padding-top: 5px;\n}\n\n#blazer-body.gba-status .gba-romance-track {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 6px;\n}\n\n#blazer-body.gba-status .gba-romance-track li {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 5px;\n  padding: 5px 7px;\n  font-family: var(--font-ui);\n  font-size: 12px;\n}\n\n#blazer-body.gba-status .gba-romance-track li:last-child { grid-column: 1 / -1; }\n\n#blazer-body.gba-status .gba-romance-track li[data-achieved='true'] {\n  border-bottom: 1px solid var(--gba-ink);\n  border-left: 4px solid var(--gba-red);\n  padding-left: 4px;\n}\n\n@media (max-width: 350px) {\n  #blazer-body.gba-status .card1 { margin: 9px 7px; padding: 10px; }\n  #blazer-body.gba-status .card1 > .ct:first-child { margin: -10px -10px 10px; }\n  #blazer-body.gba-status .roster-list { padding: 8px 7px; gap: 10px; }\n  #blazer-body.gba-status .gba-contact-summary { padding: 9px 8px; gap: 7px; }\n  #blazer-body.gba-status .roster-ava { width: 36px; height: 40px; flex-basis: 36px; font-size: 21px; }\n  #blazer-body.gba-status .roster-name { font-size: 13px; }\n  #blazer-body.gba-status .gba-contact-body { padding: 10px; }\n}\n\u003c/style>\n\u003c/head>\n\u003cbody>\n\n\u003c!-- 状态栏 -->\n\u003cdiv id=\"sys\">\n  \u003cspan class=\"sys-brand\">HAGUN / OS\u003c/span>\n  \u003cspan id=\"mono-source\" title=\"等待读取本局档案\">读取中\u003c/span>\u003cspan class=\"sys-clk num\" id=\"sys-clk\">时间未确认\u003c/span>\n  \u003cdiv class=\"sys-icons\">\n    \u003ci class=\"ti ti-flame\" title=\"魔力炉心正常\" style=\"color:#ef4444\">\u003c/i>\n    \u003ci class=\"ti ti-wifi\" style=\"color:#38bdf8\">\u003c/i>\n    \u003ci class=\"ti ti-battery-3\" style=\"color:#10b981\">\u003c/i>\n  \u003c/div>\n\u003c/div>\n\n\u003c!-- 视口堆叠 -->\n\u003cdiv id=\"stack\">\n\n  \u003c!-- 1. 首页 (Home) -->\n  \u003cdiv class=\"scr on\" id=\"scr-home\">\n    \u003cdiv class=\"home-wallpaper\">\u003c/div>\n    \u003cdiv class=\"home-content\" data-layout=\"wheel\">\n      \u003c!-- 伐刀者学生证 Widget -->\n      \u003cdiv class=\"blazer-license-card\" id=\"home-license-card\" onclick=\"openApp('blazer')\">\n        \u003cdiv class=\"mono-card-overline\">\u003cspan>HAGUN / BLAZER ID\u003c/span>\u003cspan>伐刀者证\u003c/span>\u003c/div>\u003cdiv class=\"card-top\">\n          \u003cdiv class=\"card-avatar\" id=\"home-ava\">破\u003c/div>\n          \u003cdiv class=\"card-info\">\n            \u003cdiv class=\"card-name-row\">\n              \u003cspan class=\"card-name\" id=\"home-name\">未建档\u003c/span>\n              \u003cspan class=\"card-class\" id=\"home-class\">破军学园 / 一年一班\u003c/span>\n              \u003cspan class=\"card-rank-badge\" id=\"home-rank\">F级\u003c/span>\n            \u003c/div>\n          \u003c/div>\n        \u003c/div>\n        \u003cdiv class=\"card-device-row\">\n          \u003cspan class=\"card-device-name\" id=\"home-device\">灵装未登记\u003c/span>\n          \u003cspan class=\"card-noble-art\" id=\"home-art\">体术强化系\u003c/span>\n        \u003c/div>\n        \u003cdiv class=\"card-axes-pills\" id=\"home-axes-pills\">\n          \u003cspan class=\"axis-pill\" id=\"pill-atk\">攻\u003cb>F\u003c/b>\u003c/span>\n          \u003cspan class=\"axis-pill\" id=\"pill-def\">防\u003cb>F\u003c/b>\u003c/span>\n          \u003cspan class=\"axis-pill\" id=\"pill-mp\">魔\u003cb>F\u003c/b>\u003c/span>\n          \u003cspan class=\"axis-pill\" id=\"pill-ctrl\">控\u003cb>E\u003c/b>\u003c/span>\n          \u003cspan class=\"axis-pill\" id=\"pill-phy\">体\u003cb>A\u003c/b>\u003c/span>\n          \u003cspan class=\"axis-pill\" id=\